#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_colorMode;
uniform float amzp_blendMode;
uniform float amzp_motionMode;
uniform float amzp_bandDir;
uniform float amzp_autop;
uniform float amzp_autoSpeed;
uniform float amzp_progress;
uniform float amzp_scale;
uniform float amzp_angle;
uniform float2 amzp_position;
uniform float2 amzp_stretch;
uniform float amzp_alpha;
uniform float amzp_alphaComp;
uniform float amzp_distort;
uniform float amzp_tearAmt;
uniform float amzp_tearLine;
uniform float amzp_smear;
uniform float amzp_smearSamples;
uniform float amzp_bleed;
uniform float amzp_soft;
uniform float amzp_grain;
uniform float amzp_flowAngle;
uniform float amzp_layers;
uniform float amzp_density;
uniform float amzp_outDensity;
uniform float amzp_spacing;
uniform float amzp_rowHeight;
uniform float amzp_size;
uniform float amzp_headSmooth;
uniform float amzp_tail;
uniform float amzp_speed;
uniform float amzp_speedVar;
uniform float amzp_brightness;
uniform float amzp_glow;
uniform float amzp_bands;
uniform float amzp_bandWidth;
uniform float amzp_bandCount;
uniform float amzp_bandSpeed;
uniform float amzp_lineJit;
uniform float amzp_rgbSplit;
uniform float amzp_flick;
uniform float amzp_fps;
uniform float amzp_scan;
uniform float amzp_scanSize;
layout(color) uniform half4 amzp_colA;
layout(color) uniform half4 amzp_colB;
uniform float amzp_overdrawOn;
    float2 nmRot(float2 q, float a) { float c = cos(a), s = sin(a); return float2(c * q.x - s * q.y, s * q.x + c * q.y); }
    float2 nmStd(float2 p) {
        float z = max(amzp_scale * 2.0, 0.002);
        p -= amzp_position;
        p = nmRot(p, -radians(amzp_angle));
        return p / (z * max(amzp_stretch, float2(0.01)));
    }
    float4 nmBlend(float4 tex, float4 fx) {
        float4 f = clamp(fx, 0.0, 1.0) * clamp(amzp_alpha, 0.0, 1.0);
        float4 b = tex * clamp(amzp_alphaComp, 0.0, 1.0);
        float4 o;
        if (int(amzp_blendMode) == 0) o = f;
        else if (int(amzp_blendMode) == 1) o = float4(b.rgb * (f.rgb + (1.0 - f.a)), b.a);
        else if (int(amzp_blendMode) == 2) o = float4(b.rgb + f.rgb - b.rgb * f.rgb, b.a + f.a - b.a * f.a);
        else if (int(amzp_blendMode) == 4) o = float4(b.rgb + f.rgb, max(b.a, f.a));
        else o = f + b * (1.0 - f.a);
        o = clamp(o, 0.0, 1.0);
        return float4(min(o.rgb, float3(o.a)), o.a);
    }
    float4 h4(float2 c, float k) {
        float4 p = float4(dot(c, float2(127.1, 311.7)), dot(c, float2(269.5, 183.3)), dot(c, float2(419.2, 371.9)), dot(c, float2(91.7, 57.3))) + k * float4(13.7, 7.3, 3.1, 17.9);
        return fract(sin(p) * 43758.5453);
    }
    float cometI(float du, float dv, float rad, float tailL, float aa) {
        float gHead = exp(-(du * du + dv * dv) / (rad * rad));
        float sHead = (1.0 - smoothstep(rad - aa * 0.5, rad + aa * 0.5, abs(du))) * (1.0 - smoothstep(rad - aa * 0.5, rad + aa * 0.5, abs(dv)));
        float head = mix(sHead, gHead, clamp(amzp_headSmooth, 0.0, 1.0));
        float halo = amzp_glow * exp(-sqrt(du * du + dv * dv) / (rad * 3.0));
        float tt = clamp(du / tailL, 0.0, 1.0);
        float w = rad * (1.0 - 0.75 * tt);
        float tl = du > 0.0 ? exp(-du / (tailL * 0.35)) * exp(-(dv * dv) / (w * w)) * (1.0 - smoothstep(0.7, 1.0, tt)) : 0.0;
        return head * 1.6 + halo * 0.5 + tl * 0.9;
    }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float bandMask(float bp) { return smoothstep(0.0, 0.06, bp) * (1.0 - smoothstep(amzp_bandWidth * 0.55, amzp_bandWidth, bp)); }
    float bandRoll(float T) {
        float r = abs(amzp_bandSpeed) * T;
        if (int(amzp_bandDir) == 0) return r;
        if (int(amzp_bandDir) == 1) return -r;
        float R = max(amzp_bandCount, 0.5) + amzp_bandWidth;
        float tw = r / (2.0 * R);
        return (1.0 - abs(1.0 - 2.0 * fract(tw))) * R;
    }
    void amzRender() {
        float4 lay = amzTexture(0, amzScreenNorm());
        float2 L = layer;
        float2 p0 = (amzLayerNorm() - 0.5) * L;
        float2 p = nmStd(p0);
        float2 q = nmRot(p, -radians(amzp_flowAngle));
        float aa = 1.0 / max(amzp_scale * 2.0, 0.002);
        float T = ((amzp_autop>0.5) ? time * amzp_autoSpeed : 0.0) + amzp_progress;
        float fpsT = floor(T * max(amzp_fps, 1.0));
        float nL = clamp(floor(amzp_layers + 0.5), 1.0, 16.0);
        float4 lay2 = lay;
        if ((amzp_distort>0.5)) {
            float2 zst = max(amzp_scale * 2.0, 0.002) * max(amzp_stretch, float2(0.01));
            float2 nStep = nmRot(nmRot(float2(1.0, 0.0), radians(amzp_flowAngle)) * zst, radians(amzp_angle)) / L;
            float bmL = mix(1.0, bandMask(fract((q.y / max(L.x, L.y)) * max(amzp_bandCount, 0.1) - bandRoll(T))), amzp_bands);
            float rT = (h4(float2(floor(q.y / max(amzp_tearLine, 0.5)), 77.0), fpsT).x - 0.5) * 2.0;
            float sh = sign(rT) * pow(abs(rT), 1.6) * amzp_tearAmt * bmL;
            float len = amzp_smear * bmL + amzp_soft;
            float nS = clamp(floor(amzp_smearSamples + 0.5), 2.0, 24.0);
            float4 sum = float4(0.0);
            float wsum = 0.0;
            for (int i = 0; i < 24; i++) {
                float fi = float(i);
                if (fi >= nS) break;
                float t = fi / (nS - 1.0);
                float w = exp(-t * 2.5);
                sum += amzTexture(0, l2s(amzLayerNorm() + nStep * (sh - len * t))) * w;
                wsum += w;
            }
            lay2 = sum / wsum;
            float bl = amzp_bleed * (1.0 + 2.0 * bmL);
            lay2.r = mix(lay2.r, amzTexture(0, l2s(amzLayerNorm() + nStep * (sh + bl))).r, 0.75);
            lay2.b = mix(lay2.b, amzTexture(0, l2s(amzLayerNorm() + nStep * (sh - bl))).b, 0.75);
            float gn = (h4(floor(p0), fpsT + 5.0).x - 0.5) * amzp_grain;
            lay2.rgb = clamp(lay2.rgb + gn * lay2.a, 0.0, 1.0);
            lay2.rgb = min(lay2.rgb, float3(lay2.a));
        }
        float3 acc = float3(0.0);
        for (int l = 0; l < 16; l++) {
            float fl = float(l);
            if (fl >= nL) break;
            float d = nL > 1.5 ? fl / (nL - 1.0) : 0.0;
            float sc = mix(1.0, 0.4, d);
            float S = max(amzp_spacing * sc, 4.0);
            float rowH = max(amzp_rowHeight * sc, 2.0);
            float rad = max(min(amzp_size * sc, rowH * 0.45), 0.7 * aa);
            float tailL = max(min(amzp_tail * sc, S * 0.95), rad * 2.0);
            float bright = mix(1.0, 0.5, d);
            float j = floor(q.y / rowH);
            float2 rk = float2(j, fl * 17.0 + 3.0);
            float4 hr = h4(rk, 0.0);
            float spdJ = amzp_speed * sc * (1.0 + amzp_speedVar * (hr.x - 0.5) * 2.0);
            float vcRow = (j + 0.5) * rowH;
            float bm = bandMask(fract((vcRow / max(L.x, L.y)) * max(amzp_bandCount, 0.1) - bandRoll(T)));
            float effD = amzp_density * mix(1.0, amzp_outDensity + bm * 2.7, amzp_bands);
            float jit = (h4(rk, fpsT + 1.0).x - 0.5) * amzp_lineJit * (0.35 + bm * amzp_bands * 1.5);
            float u = q.x - (hr.y * S + jit);
            float i0 = floor(u / S);
            for (int k = 0; k < 3; k++) {
                float ci = i0 + float(k) - 1.0;
                float2 ck = float2(ci, j + fl * 131.0 + 7.0);
                float4 h = h4(ck, 1.0);
                if (h.w >= effD) continue;
                float pp = h.z + T * spdJ / S;
                float ph = fract(pp);
                float dirS = spdJ < 0.0 ? -1.0 : 1.0;
                if (int(amzp_motionMode) == 1) {
                    float f2 = fract(pp * 0.5);
                    ph = 1.0 - abs(1.0 - 2.0 * f2);
                    dirS = (f2 < 0.5 ? 1.0 : -1.0) * (spdJ < 0.0 ? -1.0 : 1.0);
                } else if (int(amzp_motionMode) == 2) {
                    ph = fract(h.z);
                    dirS = 1.0;
                }
                float hu = (ci + ph) * S;
                float env = smoothstep(0.0, 0.12, ph) * (1.0 - smoothstep(0.8, 1.0, ph));
                float vc = vcRow + (h.y - 0.5) * max(rowH - 3.0 * rad, 0.0);
                float dv = q.y - vc;
                float du = (hu - u) * dirS;
                float sep = amzp_rgbSplit * sc;
                if (du < -rad * 4.0 - sep || du > tailL * 1.3 + rad * 4.0 + sep || abs(dv) > rad * 4.0) continue;
                float flk = mix(1.0, h4(ck, fpsT).x, amzp_flick);
                float3 col;
                if (int(amzp_colorMode) == 0) {
                    col = float3(cometI(du + sep, dv, rad, tailL, aa), cometI(du, dv, rad, tailL, aa), cometI(du - sep, dv, rad, tailL, aa)) * amzp_colA.rgb;
                } else {
                    float I = cometI(du, dv, rad, tailL, aa);
                    if (int(amzp_colorMode) == 1) col = float3(I);
                    else if (int(amzp_colorMode) == 2) col = mix(amzp_colA.rgb, amzp_colB.rgb, clamp(du / tailL, 0.0, 1.0)) * I;
                    else if (int(amzp_colorMode) == 3) col = amzp_colA.rgb * I;
                    else col = (0.5 + 0.5 * cos(6.2831853 * (h.x + float3(0.0, 0.33, 0.67)))) * I;
                }
                acc += col * env * flk * bright * amzp_brightness;
            }
        }
        float sl = 1.0 - amzp_scan * (0.5 - 0.5 * cos(6.2831853 * p.y / max(amzp_scanSize, 1.0)));
        acc *= sl;
        acc = clamp(acc, 0.0, 1.0);
        float a = max(max(acc.r, acc.g), acc.b);
        amzOutput = nmBlend(lay2, float4(acc, a));
        if (!(amzp_overdrawOn>0.5)) amzOutput *= lay.a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
